  /**
   * Show a toast notification (corner position)
   */
  _showToast(message, type, options = {}) {
    const container = document.getElementById('form-notification-container');
    const toast = document.createElement('div');
    toast.className = `fn-toast fn-toast-${type}`;
    
    const title = options.title ?? this._getDefaultTitle(type);
    
    toast.innerHTML = `
      <div class="fn-toast-icon">${this._getIcon(type)}</div>
      <div class="fn-toast-content">
