    container.appendChild(toast);
    this.activeToasts.add(toast);

    const closeToast = () => {
      if (!this.activeToasts.has(toast)) return;
      toast.classList.add('fn-removing');
      setTimeout(() => {
        toast.remove();
        this.activeToasts.delete(toast);
        options.onClose?.();
      }, 200);
    };

    toast.querySelector('.fn-toast-close').addEventListener('click', closeToast);

    let timeoutId = null;
    const autoClose = options.autoClose ?? true;
    if (autoClose) {
      const duration = options.duration ?? this.options.autoCloseDelay;
      timeoutId = setTimeout(closeToast, duration);
    }

    return {
