  /**
   * Show a modal notification (centered)
   */
  _showModal(message, type, options = {}) {
    return new Promise((resolve) => {
      const title = options.title ?? this._getDefaultTitle(type);
      const buttonText = options.buttonText ?? 'OK';
      const buttonStyle = options.buttonStyle ?? this._getButtonStyleForType(type);

      const overlay = document.createElement('div');
      overlay.className = 'fn-modal-overlay';
      
      overlay.innerHTML = `
        <div class="fn-modal fn-modal-message fn-modal-${type}">
          <div class="fn-modal-header">
            <div class="fn-modal-icon">${this._getIcon(type)}</div>
