   * @param {Object} options - { mode: 'toast'|'modal', title, autoClose, duration, onClose, buttonText, buttonStyle }
   */
  warning(message, options = {}) {
    return this._showNotification(message, 'warning', options);
  }

  /**
   * Show info message
   * @param {string} message - The message to display
   * @param {Object} options - { mode: 'toast'|'modal', title, autoClose, duration, onClose, buttonText, buttonStyle }
   */
  info(message, options = {}) {
    return this._showNotification(message, 'info', options);
  }

  /**
   * Show confirmation dialog
   * @param {Object} config - Configuration object
   * @param {string} config.title - Modal title
   * @param {string} config.message - Modal message/content (can include HTML)
   * @param {string} [config.confirmText='Yes'] - Confirm button text
   * @param {string} [config.cancelText='No'] - Cancel button text
   * @param {string} [config.confirmStyle='primary'] - 'primary' | 'danger' | 'success' | 'warning'
   * @param {string} [config.type='confirm'] - Icon type: 'confirm' | 'warning' | 'error' | 'info'
   * @param {string} [config.confirmEvent] - Event name to emit on confirm (via customEvent)
   * @param {Object} [config.confirmEventData] - Additional data to include with confirm event
   * @param {string} [config.cancelEvent] - Event name to emit on cancel (via customEvent)
   * @param {Object} [config.cancelEventData] - Additional data to include with cancel event
   * @param {Function} [config.onConfirm] - Callback on confirm
   * @param {Function} [config.onCancel] - Callback on cancel
   * @returns {Promise<boolean>} - Resolves true if confirmed, false if cancelled
   */
  confirm(config) {
    return new Promise((resolve) => {
      const {
        title = 'Confirm',
        message,
        confirmText = 'Yes',
        cancelText = 'No',
        confirmStyle = 'primary',
        type = 'confirm',
        confirmEvent,
        confirmEventData = {},
        cancelEvent,
        cancelEventData = {},
        onConfirm,
        onCancel
      } = config;

      const overlay = document.createElement('div');
      overlay.className = 'fn-modal-overlay';
      
      overlay.innerHTML = `
        <div class="fn-modal">
          <div class="fn-modal-header">
            <div class="fn-modal-icon">${this._getIcon(type)}</div>
            <div class="fn-modal-title">${title}</div>
            <button class="fn-modal-close" aria-label="Close">${this._getCloseIcon()}</button>
          </div>
          <div class="fn-modal-body">${message}</div>
          <div class="fn-modal-footer">
            <button class="fn-btn fn-btn-secondary" data-action="cancel">${cancelText}</button>
            <button class="fn-btn fn-btn-${confirmStyle}" data-action="confirm">${confirmText}</button>
          </div>
        </div>
      `;

      document.body.appendChild(overlay);
      this.activeModals.add(overlay);

      const closeModal = (confirmed) => {
        if (!this.activeModals.has(overlay)) return;
        overlay.classList.add('fn-removing');
        setTimeout(() => {
          overlay.remove();
          this.activeModals.delete(overlay);
          
          if (confirmed) {
            onConfirm?.();
            if (confirmEvent && this.instance?.emit) {
              this.instance.emit('customEvent', { type: confirmEvent, ...confirmEventData });
            }
          } else {
            onCancel?.();
            if (cancelEvent && this.instance?.emit) {
              this.instance.emit('customEvent', { type: cancelEvent, ...cancelEventData });
            }
          }
          
          resolve(confirmed);
        }, 200);
      };

      overlay.addEventListener('click', (e) => {
        const action = e.target.dataset?.action;
        if (action === 'confirm') {
          closeModal(true);
        } else if (action === 'cancel' || e.target.classList.contains('fn-modal-close')) {
          closeModal(false);
        } else if (e.target === overlay) {
          closeModal(false);
        }
      });

      const handleEscape = (e) => {
        if (e.key === 'Escape') {
          document.removeEventListener('keydown', handleEscape);
          closeModal(false);
        }
      };
      document.addEventListener('keydown', handleEscape);
    });
  }

  /**
   * Convenience method for delete confirmation
   */
  confirmDelete(message, options = {}) {
    return this.confirm({
      title: options.title || 'Confirm Delete',
      message,
      confirmText: options.confirmText || 'Delete',
      cancelText: options.cancelText || 'Cancel',
      confirmStyle: 'danger',
      type: 'warning',
      ...options
    });
  }

  /**
   * Convenience method for exit/discard confirmation
   */
  confirmExit(message, options = {}) {
    return this.confirm({
      title: options.title || 'Unsaved Changes',
      message,
      confirmText: options.confirmText || 'Leave',
      cancelText: options.cancelText || 'Stay',
      confirmStyle: 'danger',
      type: 'warning',
      ...options
    });
  }

  /**
   * Clear all active toasts
   */
  clearToasts() {
    this.activeToasts.forEach(toast => {
      toast.classList.add('fn-removing');
      setTimeout(() => toast.remove(), 200);
    });
    this.activeToasts.clear();
  }

  /**
   * Clear all active modals
   */
  clearModals() {
    this.activeModals.forEach(modal => {
      modal.classList.add('fn-removing');
      setTimeout(() => modal.remove(), 200);
    });
    this.activeModals.clear();
  }

  /**
   * Clear all notifications (toasts and modals)
   */
  clearAll() {
    this.clearToasts();
    this.clearModals();
  }

  /**
   * Destroy the notification system
   */
  destroy() {
    this.clearAll();
    document.getElementById('form-notification-container')?.remove();
    document.getElementById('form-notification-styles')?.remove();
  }
}

