class FileViewer {
  constructor(apiBaseUrl, statusCallback = null) {
    this.apiBaseUrl = apiBaseUrl;
    this.statusCallback = statusCallback;
    this.currentFileUrl = null;
  }

  /**
   * Get current auth token from storage
   * @returns {string|null}
   * @private
   */
  _getAuthToken() {
    const token = localStorage.getItem('AUTH_TOKEN');
    if (!token) {
      this.showStatus('Authentication token not found', 'error');
    }
    return token;
  }

  /**
   * Show status message using provided callback or console
   */
  showStatus(message, type) {
    if (this.statusCallback && typeof this.statusCallback === 'function') {
      this.statusCallback(message, type);
    } else {
      console.log(`[${type.toUpperCase()}] ${message}`);
    }
  }

  /**
   * Get presigned URL for file
   * @param {string} filename - File name to fetch
   * @param {number} expiry - URL expiry time in seconds (default: 600)
   * @returns {Promise<string>} - Presigned URL
   * @private
   */
  async _getPresignedUrl(filename, expiry) {
    const authToken = this._getAuthToken();
    if (!authToken) {
      throw new Error('Authentication token not found');
    }

    const url = `${this.apiBaseUrl}/api/v1/files/url/${filename}?expiry=${expiry}`;

    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${authToken}`,
      },
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    const data = await response.json();

    if (!data.url) {
      throw new Error('No presigned URL in response');
    }

    return data.url;
  }

  /**
   * Fetch file and open in new tab using presigned URL
   * @param {string} filename - File name to fetch (e.g., 'MV6020-1180201.pdf')
   * @param {number} expiry - URL expiry time in seconds (default: 600)
   * @returns {Promise<boolean>} - Success status
   */
  async openFile(filename, expiry = 600) {
    try {
      this.showStatus('Fetching file...', 'info');

      const presignedUrl = await this._getPresignedUrl(filename, expiry);

      const newWindow = window.open(presignedUrl, '_blank');

      if (newWindow) {
        return true;
      } else {
        this.showStatus('File fetched but popup was blocked. Please allow popups for this site.', 'error');
        return false;
      }

    } catch (error) {
      console.error('Error opening file:', error);
      this.showStatus(`Error: ${error.message}`, 'error');
      throw error;
    }
  }

  /**
   * Download file using presigned URL
   * @param {string} filename - File name to fetch
   * @param {string} downloadAs - Optional custom download filename
   * @param {number} expiry - URL expiry time in seconds (default: 600)
   * @returns {Promise<boolean>} - Success status
   */
  async downloadFile(filename, downloadAs = null, expiry = 600) {
    try {
      this.showStatus('Downloading file...', 'info');

      const presignedUrl = await this._getPresignedUrl(filename, expiry);

      const downloadLink = document.createElement('a');
      downloadLink.href = presignedUrl;
      downloadLink.download = downloadAs || filename;

      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);

      return true;

    } catch (error) {
      console.error('Error downloading file:', error);
      this.showStatus(`Error: ${error.message}`, 'error');
      throw error;
    }
  }

  /**
   * Open file as blob in new tab (legacy API)
   * @param {string} filename - File name to fetch
   * @returns {Promise<boolean>} - Success status
   */
  async openFileAsBlob(filename) {
    try {
      const authToken = this._getAuthToken();
      if (!authToken) {
        throw new Error('Authentication token not found');
      }

      const url = `${this.apiBaseUrl}/api/v1/files/${filename}`;

      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${authToken}`,
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const fileBlob = await response.blob();
      const blobUrl = URL.createObjectURL(fileBlob);

      // Clean up previous file URL if exists
      this.cleanup();

      // Store current URL for cleanup
      this.currentFileUrl = blobUrl;

      // Open in new tab
      const newWindow = window.open(blobUrl, '_blank');

      if (newWindow) {
        // Clean up URL when window is closed or after load
        newWindow.addEventListener('beforeunload', () => {
          this.cleanup();
        });

        return true;
      } else {
        this.showStatus('File fetched but popup was blocked. Please allow popups for this site.', 'error');
        this.cleanup();
        return false;
      }

    } catch (error) {
      console.error('Error opening file:', error);
      this.showStatus(`Error: ${error.message}`, 'error');
      throw error;
    }
  }

  /**
   * Download file as blob (legacy API)
   * @param {string} filename - File name to fetch
   * @param {string} downloadAs - Optional custom download filename
   * @returns {Promise<boolean>} - Success status
   */
  async downloadFileAsBlob(filename, downloadAs = null) {
    try {
      const authToken = this._getAuthToken();
      if (!authToken) {
        throw new Error('Authentication token not found');
      }

      const url = `${this.apiBaseUrl}/api/v1/files/${filename}`;

      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${authToken}`,
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const fileBlob = await response.blob();
      const downloadUrl = URL.createObjectURL(fileBlob);

      const downloadLink = document.createElement('a');
      downloadLink.href = downloadUrl;
      downloadLink.download = downloadAs || filename;

      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);

      URL.revokeObjectURL(downloadUrl);

      return true;

    } catch (error) {
      console.error('Error downloading file:', error);
      this.showStatus(`Error: ${error.message}`, 'error');
      throw error;
    }
  }

  /**
   * Clean up blob URLs
   */
  cleanup() {
    if (this.currentFileUrl) {
      URL.revokeObjectURL(this.currentFileUrl);
      this.currentFileUrl = null;
    }
  }
}

