class PDFGeneration {
    constructor(apiUrl, emailUrl, statusCallback = null) {
        this.apiUrl = apiUrl;
        this.emailUrl = emailUrl;
        this.statusCallback = statusCallback;
        this.currentPdfBlob = null;
        this.currentPdfUrl = null;
    }

    /**
     * Get fresh auth token from localStorage
     * @returns {string|null} - Auth token or null if not found
     */
    getAuthToken() {
        const token = localStorage.getItem('AUTH_TOKEN');
        if (!token) {
            this.showStatus('Your session has expired. Please sign in again.', 'error');
        }
        return token;
    }

    /**
     * Build headers with fresh auth token
     * @returns {Object|null} - Headers object or null if no token
     */
    buildHeaders() {
        const token = this.getAuthToken();
        if (!token) return null;

        return {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
        };
    }

    /**
     * Show status message using provided callback or console
     */
    /* showStatus(message, type = 'info') {
        if (this.statusCallback && typeof this.statusCallback === 'function') {
            this.statusCallback(message, type);
        } else {
            console.log(`[${type.toUpperCase()}] ${message}`);
        }
    } */

    showStatus(message, type) {
        // Get notification handler from hidden component
        const notification = instance.root.getComponent('notification');
        
        if (notification?.notify) {
            // Decide mode: modal for success/error, toast for others
            const mode =
            type === 'success' || type === 'error' ? 'modal' : 'toast';
        
            notification.notify[type](message, { mode });
        } else {
            console.log(`[${type.toUpperCase()}] ${message}`);
        }
        }   

    /**
     * Build request data object
     */
    // Change report PoC: send the parent revision with every print, preview, download and email
    // request, so the DF API can highlight what changed. It is read from Form.io with the
    // officer's token, as Load original does, and kept in memory only (never saved with the form).
    // Without it the report still prints, with a banner saying changes could not be highlighted.
    async parentDataFor(data) {
        const ids = /^[0-9a-f]{24}$/;
        if (!data || !data.isChangeReport || !ids.test(data.parentFormId || '') || !ids.test(data.parentSubmissionId || '')) {
            return {};
        }
        const key = `${data.parentFormId}/${data.parentSubmissionId}`;
        if (this.parentCache && this.parentCache.key === key) {
            return { parentData: this.parentCache.data };
        }
        try {
            const env = window._env_ || {};
            const projectUrl = env.REACT_APP_API_PROJECT_URL || env.REACT_APP_API_SERVER_URL;
            const token = localStorage.getItem('formioToken');
            if (!projectUrl || !token) return {};
            const response = await fetch(`${projectUrl}/form/${data.parentFormId}/submission/${data.parentSubmissionId}`,
                                         { headers: { 'x-jwt-token': token } });
            if (!response.ok) {
                console.warn('[MV6020 change report] parent revision not available for highlights:', response.status);
                return {};
            }
            const parent = await response.json();
            if (!parent || !parent.data) return {};
            this.parentCache = { key, data: parent.data };
            return { parentData: parent.data };
        } catch (e) {
            // Names only: never log submission contents.
            console.warn('[MV6020 change report] parent revision not available for highlights:', e && e.name);
            return {};
        }
    }

    buildRequestData(templateName, data) {
        return {
            template: templateName,
            data: data
        };
    }

    /**
     * Render HTML and open in new tab
     */
    async renderHTML(templateName, data) {
        const headers = this.buildHeaders();
        if (!headers) return false;

        try {
            this.showStatus('Preparing your document...', 'info');
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const htmlRequestData = {
                ...requestData,
                options: { type: "html", filename: `mv6020.html` }
            };

            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(htmlRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            const html = await response.text();
            const blob = new Blob([html], { type: 'text/html' });
            const blobUrl = URL.createObjectURL(blob);
            const newWindow = window.open(blobUrl, '_blank');

            if (newWindow) {
                newWindow.addEventListener('load', () => {
                    this.showStatus('Your document preview is ready.', 'success');

                    // Revoke ONLY after success notification
                    URL.revokeObjectURL(blobUrl);
                });
                return true;
            } else {
                this.showStatus(
                    'Your document is ready, but the preview was blocked by your browser. Please enable pop-ups for this site and try again.',
                    'error'
                  );
                URL.revokeObjectURL(blobUrl);
                return false;
            }
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        }
    }

    /**
     * Generate and download PDF
     */
    async downloadPDF(templateName, data, fileName = 'document.pdf') {
        const headers = this.buildHeaders();
        if (!headers) return false;

        try {
            this.showStatus('Preparing your document...', 'info');
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const pdfRequestData = {
                ...requestData,
                options: { type: "pdf", filename: `${fileName}` }
            };

            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(pdfRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            const pdfBlob = await response.blob();
            const downloadUrl = URL.createObjectURL(pdfBlob);
            const downloadLink = document.createElement('a');
            downloadLink.href = downloadUrl;
            downloadLink.download = `${fileName}`;
            document.body.appendChild(downloadLink);
            downloadLink.click();
            document.body.removeChild(downloadLink);
            URL.revokeObjectURL(downloadUrl);

            this.showStatus('Your document has been downloaded.', 'success');
            return true;
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        }
    }

    async sendEmail(templateName, data, fileName = 'document') {
        const headers = this.buildHeaders();
        if (!headers) return false;

        try {
            this.showStatus('Sending your email...', 'info');
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const emailRequestData = {
                ...requestData,
                options: { type: "email", filename: `${fileName}.pdf` }
            };

            const response = await fetch(this.emailUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(emailRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            this.showStatus('Your email has been sent.', 'success');
            return true;
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        }
    }

    /**
     * Generate PDF and return as blob
     */
    async generatePDFBlob(templateName, data) {
        const headers = this.buildHeaders();
        if (!headers) return null;

        try {
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const pdfRequestData = {
                ...requestData,
                options: { type: "pdf" }
            };

            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(pdfRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            return await response.blob();
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        }
    }

    /**
     * Generate PDF and open in new tab (CSP-safe)
     */
    async previewPDF(templateName, data, button = null) {
        if (button) {
            button.disabled = true;
            button.textContent = 'Loading Preview...';
        }

        const headers = this.buildHeaders();
        if (!headers) {
            if (button) {
                button.disabled = false;
                button.textContent = 'PDF Preview';
            }
            return false;
        }

        try {
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const pdfRequestData = {
                ...requestData,
                options: { type: "pdf", filename: "preview.pdf" }
            };

            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(pdfRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            const pdfBlob = await response.blob();
            const pdfUrl = URL.createObjectURL(pdfBlob);

            this.closePreview();
            this.currentPdfBlob = pdfBlob;
            this.currentPdfUrl = pdfUrl;

            const newWindow = window.open(pdfUrl, '_blank');
            if (newWindow) {
                newWindow.addEventListener('beforeunload', () => {
                    this.closePreview();
                });
                newWindow.addEventListener('load', () => {
                    this.showStatus('Your document is ready to print.', 'success');

                    // Release blob URL after the window finishes loading
                     URL.revokeObjectURL(pdfUrl);
                });
                return true;
            } else {
                this.showStatus('Your document is ready, but your browser blocked the preview window. Please enable pop-ups for this site and try again.', 'error');
                this.closePreview();
                return false;
            }
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        } finally {
            if (button) {
                button.disabled = false;
                button.textContent = 'PDF Preview';
            }
        }
    }

    /**
     * Generate PDF preview and display in viewer
     */
    async previewPDF1(templateName, data, previewContainer, pdfViewer, button = null) {
        if (button) {
            button.disabled = true;
            button.textContent = 'Loading Preview...';
        }

        const headers = this.buildHeaders();
        if (!headers) {
            if (button) {
                button.disabled = false;
                button.textContent = 'PDF Preview';
            }
            return false;
        }

        try {
            this.showStatus('Preparing a preview of your document...', 'info');
            const requestData = { ...this.buildRequestData(templateName, data), ...(await this.parentDataFor(data)) };
            const pdfRequestData = {
                ...requestData,
                options: { type: "pdf", filename: "preview.pdf" }
            };

            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify(pdfRequestData)
            });

            if (!response.ok) {
                // throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                throw new Error(FRIENDLY_MESSAGES[response.status] ||
                    'An unexpected error occurred. Please try again later.');
            }

            const pdfBlob = await response.blob();
            const pdfUrl = URL.createObjectURL(pdfBlob);

            this.closePreview();
            this.currentPdfBlob = pdfBlob;
            this.currentPdfUrl = pdfUrl;

            pdfViewer.src = pdfUrl;
            previewContainer.classList.remove('hidden');
            previewContainer.scrollIntoView({ behavior: 'smooth' });

            this.showStatus('Your document preview is ready.', 'success');

            return true;
        } catch (error) {
            console.error('Error:', error);
            this.showStatus(`Error: ${error.message}`, 'error');
            throw error;
        } finally {
            if (button) {
                button.disabled = false;
                button.textContent = 'PDF Preview';
            }
        }
    }

    /**
     * Download PDF from current preview
     */
    downloadFromPreview(fileName = 'custom_name') {
        if (!this.currentPdfBlob) {
            this.showStatus('There is no document available to download yet.', 'error');
            return false;
        }

        try {
            const downloadUrl = URL.createObjectURL(this.currentPdfBlob);
            const downloadLink = document.createElement('a');
            downloadLink.href = downloadUrl;
            downloadLink.download = `${fileName}.pdf`;
            document.body.appendChild(downloadLink);
            downloadLink.click();
            document.body.removeChild(downloadLink);
            URL.revokeObjectURL(downloadUrl);

            this.showStatus('Your document has been downloaded. You can open it from your downloads folder.', 'success');
            return true;
        } catch (error) {
            console.error('Error downloading from preview:', error);
            this.showStatus(`Download error: ${error.message}`, 'error');
            return false;
        }
    }

    /**
     * Close current PDF preview and cleanup
     */
    closePreview(previewContainer = null, pdfViewer = null) {
        if (previewContainer) {
            previewContainer.classList.add('hidden');
        }
        if (pdfViewer) {
            pdfViewer.src = '';
        }
        if (this.currentPdfUrl) {
            URL.revokeObjectURL(this.currentPdfUrl);
            this.currentPdfUrl = null;
        }
        this.currentPdfBlob = null;
    }

    /**
     * Check if preview is currently available
     */
    isPreviewAvailable() {
        return this.currentPdfBlob !== null;
    }
}

