async function getAndSaveFormId(formType = "24Hour", maxRetries = 5, retryDelay = 1000) {
  let retries = 0;
  let value = null;
  while (retries < maxRetries) {
    try {
      value = await window.getNextAvailableFormId(formType);
      console.log(funcName, `Retrieved form ID ${formType}:`, value);
      if (value !== null) {
        return value; // Success! Return the value
      } else {
        console.log(funcName, `No available form ID found on attempt ${retries + 1}. Retrying...`);
        retries++;
        // Wait before retrying
        await new Promise(resolve => setTimeout(resolve, retryDelay));
      }
    } catch (error) {
      console.error(funcName, `Error getting form ID (attempt ${retries + 1}):`, error);
      retries++;
      // Wait before retrying
      await new Promise(resolve => setTimeout(resolve, retryDelay));
    }
  }
  console.error(funcName, `Failed to get form ID after ${maxRetries} attempts`);
  return null;
}

