// MV6020 change report: "Load original" button (proof of concept).
// Three calls, then one atomic prefill. Any failure leaves the form untouched.
//   1. DF API      GET  {RSBC_API_URL}/api/v1/collision/metadata/{case no}  -> revisions; the latest is the parent
//   2. formsflow   GET  {WEB_BASE_URL}/application/{id}                   -> formId, submissionId
//   3. Form.io     GET  {PROJECT_URL}/form/{formId}/submission/{subId}    -> original data
// Never log submission contents: they hold personal information.
(async function () {
  const notify = instance.root.getComponent('notification')?.notify;
  const say = (type, message) => notify ? notify[type](message, { mode: type === 'error' ? 'modal' : 'toast' }) : window.toast?.[type]?.(message);
  const env = window._env_ || {};

  // Never copied from the parent: system, session or change-report fields (see POC_README.md).
  // form_number, collision_case_prefix and collision_case_num ARE copied: a change report
  // is a new revision of the same collision case number.
  const DENYLIST = [
    'applicationId', 'applicationStatus',
    'currentUser', 'completed_by_id', 'submitterEmail', 'submitterFirstName', 'submitterLastName',
    'currentUserRole', 'form_version', 'submitted_offline', 'print_options', 'print_options_summary',
    'form_details', 'dashboardColumns', 'notification', 'fileViewer', 'icbc_submission_date',
    'summary_was_verified', 'completed_by_name', 'officer_badge_no', 'agency', 'officer_email',
    'reportType', 'isChangeReport', 'collisionNumber', 'parentSubmissionId', 'parentRevision', 'parentFormId', 'parentFormEdition'
  ];

  class LoadError extends Error {}

  async function getJson(url, headers, step, notFound) {
    let response;
    try {
      response = await fetch(url, { headers });
    } catch (e) {
      throw new LoadError(`${step}: the service could not be reached. Check your connection and try again.`);
    }
    if (response.ok) return response.json();
    const messages = {
      401: 'your session has expired. Sign in again.',
      403: 'you do not have access to this report.',
      404: 'no submitted MV6020 was found for that collision case number.'
    };
    if (response.status === 404 && notFound) throw new LoadError(`${step}: ${notFound}`);
    throw new LoadError(`${step}: ${messages[response.status] || `unexpected response (${response.status}).`}`);
  }

  // Keys the live form can hold: {key: {}} for fields, {key: {grid: {...}}} for edit grids,
  // {key: {calculated: true}} for fields the form always recalculates (e.g. countable_fatal_total).
  function schemaOf(components, out = {}) {
    (components || []).forEach(c => {
      if (Array.isArray(c.columns)) c.columns.forEach(col => schemaOf(col.components, out));
      // Tables have rows of cells; textareas have rows as a line count.
      if (Array.isArray(c.rows)) c.rows.forEach(row => (Array.isArray(row) ? row : []).forEach(cell => schemaOf(cell?.components, out)));
      if (c.type === 'editgrid' || c.type === 'datagrid') {
        out[c.key] = { grid: schemaOf(c.components, {}) };
        return;
      }
      if (c.input && c.key && c.type !== 'button' && c.persistent !== false) {
        out[c.key] = c.calculateValue && !c.allowCalculateOverride ? { calculated: true } : {};
      }
      if (c.components) schemaOf(c.components, out);
    });
    return out;
  }

  function filterToSchema(source, schema, denylist, skipped, prefix = '') {
    const result = {};
    Object.keys(source || {}).forEach(key => {
      if (denylist.includes(key)) return;
      if (!schema[key]) { skipped.push(prefix + key); return; }
      const grid = schema[key].grid;
      result[key] = grid && Array.isArray(source[key])
        ? source[key].map((row, i) => filterToSchema(row, grid, [], skipped, `${prefix}${key}[${i}].`))
        : source[key];
    });
    return result;
  }

  const caseNumber = (data.collisionNumber || '').trim().toUpperCase();
  if (!caseNumber) { say('error', 'Enter the original collision case number.'); return; }
  const authToken = localStorage.getItem('AUTH_TOKEN');
  const formioToken = localStorage.getItem('formioToken');
  if (!authToken || !formioToken) { say('error', 'Your session has expired. Sign in again.'); return; }
  const button = instance.refs?.button;
  if (button) button.disabled = true;

  try {
    say('info', `Loading report ${caseNumber}...`);
    const bearer = { Authorization: `Bearer ${authToken}` };
    const metadata = await getJson(`${env.REACT_APP_RSBC_API_URL}/api/v1/collision/metadata/${encodeURIComponent(caseNumber)}`, bearer, 'Report lookup');
    // No branching: a change report is always created from the latest revision.
    const revisions = metadata.revisions || [];
    const parent = revisions[revisions.length - 1];
    if (!parent || !parent.ff_application_id) throw new LoadError('Report lookup: the latest revision is still being processed. Try again in a few minutes.');
    const application = await getJson(`${env.REACT_APP_WEB_BASE_URL}/application/${parent.ff_application_id}`, bearer, 'Application lookup');
    if (!application.formId || !application.submissionId) throw new LoadError('Application lookup: the application has no linked submission.');
    const projectUrl = env.REACT_APP_API_PROJECT_URL || env.REACT_APP_API_SERVER_URL;
    const original = await getJson(`${projectUrl}/form/${application.formId}/submission/${application.submissionId}`,
                                   { 'x-jwt-token': formioToken }, 'Submission load',
                                   'the original is no longer available. Reports are kept for 90 days; older reports cannot be changed in Digital Forms.');
    if (!original || !original.data) throw new LoadError('Submission load: the original submission is empty.');
    if ((original.data.collision_case_num || '').toUpperCase() !== caseNumber) {
      throw new LoadError('Submission load: the loaded submission does not match that collision case number.');
    }

    // Build the complete new data set before touching the form.
    const skipped = [];
    const schema = schemaOf(instance.root.form.components);
    const copied = filterToSchema(original.data, schema, DENYLIST, skipped);
    const current = JSON.parse(JSON.stringify(instance.root.submission.data || {}));
    const next = Object.assign({}, current, copied, {
      reportType: 'change',
      isChangeReport: true,
      collisionNumber: caseNumber,
      parentSubmissionId: original._id,
      parentRevision: parent.revision,
      // Camunda reads the parent from Form.io for the ICBC change highlights; it may be on another form version.
      parentFormId: application.formId,
      parentFormEdition: original.data.form_details?.form_version || parent.form_version || ''
    });

    // Load as a submission, as Form.io does when it opens a saved report: fields stay pristine.
    // With modified: true every field counted as edited by the officer, and a select with
    // clearOnRefresh clears itself when the field it watches is not pristine (formio.js
    // Select.refresh): status_option was cleared when refresh_status_options was recalculated.
    const flags = { noValidate: true, fromSubmission: true, resetValue: false };
    const settle = () => new Promise(resolve => setTimeout(resolve, 500));
    const apply = data => {
      form.setValue({ data }, flags);
      const calculator = instance.root.getComponent('entityNumberCalculator');
      const entities = instance.root.getComponent('entities');
      if (calculator?.entityNumberCalculator && entities) calculator.entityNumberCalculator.recalculateEntityNumbers(entities);
      form.redraw();
    };

    // Paths (never values) of copied data that form logic changed after apply, e.g.
    // entities[0].involved_persons[0].status_option. Grid rows are compared row by row.
    const stable = v => Array.isArray(v) ? v.map(stable)
      : (v && typeof v === 'object') ? Object.keys(v).sort().reduce((o, k) => { o[k] = stable(v[k]); return o; }, {})
      : v;
    // A text field can hold 0 where the saved data has "0"; that is not a change.
    const numeric = v => (typeof v === 'number' || (typeof v === 'string' && v.trim() !== '')) && !isNaN(Number(v));
    const same = (a, b) => (numeric(a) && numeric(b) && Number(a) === Number(b))
      || JSON.stringify(stable(a ?? null)) === JSON.stringify(stable(b ?? null));
    const isRows = v => Array.isArray(v) && v.every(r => r && typeof r === 'object' && !Array.isArray(r));
    // Overlay wanted values on the live data, row by row in grids, so values the form computed
    // itself (client-only fields such as refresh_status_options) are kept instead of reset.
    function overlay(live, wanted) {
      const result = Object.assign({}, live);
      Object.keys(wanted || {}).forEach(key => {
        const want = wanted[key], have = (live || {})[key];
        result[key] = isRows(want) && isRows(have) && want.length === have.length
          ? want.map((row, i) => overlay(have[i], row))
          : want;
      });
      return result;
    }
    // Calculated fields go to `recalculated`, not `lost`: the form derives them from the copied data.
    function changedPaths(expected, actual, fields = schema, prefix = '', recalculated = []) {
      const paths = [];
      Object.keys(expected || {}).forEach(key => {
        const want = expected[key], have = (actual || {})[key];
        const field = fields[key] || {};
        if (isRows(want) && isRows(have) && want.length === have.length && want.length) {
          want.forEach((row, i) => paths.push(...changedPaths(row, have[i], field.grid || {}, `${prefix}${key}[${i}].`, recalculated)));
        } else if (!same(want, have)) {
          (field.calculated ? recalculated : paths).push(prefix + key);
        }
      });
      return paths;
    }

    let firstPass = [];
    try {
      apply(next);
      // Some rules fire once on load and clear what was just set: refresh_status_options is never
      // saved, so it is recalculated and status_option (clearOnRefresh) is cleared, which hides the
      // person panel and clears the injury fields (clearOnHide). Applying again once the form has
      // settled, over the data the form now holds, doesn't re-trigger them: their inputs no longer change.
      await settle();
      firstPass = changedPaths(copied, instance.root.submission.data);
      if (firstPass.length) apply(overlay(JSON.parse(JSON.stringify(instance.root.submission.data)), next));
    } catch (e) {
      form.setValue({ data: current }, flags);
      form.redraw();
      throw new LoadError('Prefill failed and the form was restored. Start a new report or try again.');
    }

    // What still differs after the second pass is what form rules changed for good.
    // Paths only, never values: the evidence for the live-prefill vs fallback finding.
    await settle();
    const recalculated = [];
    const lost = changedPaths(copied, instance.root.submission.data, schema, '', recalculated);
    // The data can be right while a field in a nested grid row still shows (and validates) another
    // value. Compare each field's own value too, by its path, e.g. entities[0].involved_persons[0].status_option.
    const valueAt = (obj, path) => path.split(/\.|\[(\d+)\]/).filter(Boolean).reduce((o, k) => (o == null ? undefined : o[k]), obj);
    const fieldsShowingOther = () => {
      const found = [];
      instance.root.everyComponent?.(comp => {
        const def = comp.component || {};
        if (!def.input || !comp.path || def.type === 'editgrid' || def.type === 'datagrid' || def.type === 'button') return;
        if (def.calculateValue && !def.allowCalculateOverride) return;
        const want = valueAt(copied, comp.path);
        if (want !== undefined && !same(want, comp.dataValue)) found.push({ comp, want });
      });
      return found;
    };
    // Repair them by setting the field itself, then let the form settle.
    const repaired = fieldsShowingOther().map(({ comp, want }) => { comp.setValue(want, flags); return comp.path; });
    if (repaired.length) await settle();
    const notShown = fieldsShowingOther().map(({ comp }) => comp.path);

    // Errors raised while the first pass had fields blank (e.g. "Status is required" on a person
    // row) stay listed until that row is validated again. Re-check so only current errors show.
    instance.root.everyComponent?.(comp => {
      if (comp.component?.type === 'editgrid' && Array.isArray(comp.editRows)) {
        comp.editRows.forEach(row => { if (typeof comp.validateRow === 'function') comp.validateRow(row, false); });
      }
    });
    const valid = instance.root.checkValidity?.(instance.root.submission.data, true);
    form.redraw();

    // Paths and validation messages only (e.g. "Status is required"), never values.
    const errors = (instance.root.errors || []).map(e => `${e.formattedKeyOrPath || e.context?.path || e.instance?.path || e.path || e.component?.key || '?'}: ${e.message}`);

    // Diagnostic to run in the console after opening an entity: the state of every Status field,
    // and whether the stored value matches one of its options. No values are printed.
    window.__mv6020Check = (key = 'status_option') => {
      const rows = [];
      instance.root.everyComponent?.(comp => {
        if (comp.component?.key !== key) return;
        const value = comp.dataValue;
        const options = comp.selectOptions || comp.selectItems || [];
        rows.push({
          path: comp.path,
          dataEmpty: comp.isEmpty ? comp.isEmpty(value) : value == null,
          valueShape: value && typeof value === 'object' ? Object.keys(value).sort().join(',') : typeof value,
          options: options.length,
          matchesOption: options.some(o => same(o.value, value) || same(o, value)),
          pristine: comp.pristine,
          visible: comp.visible,
          onScreen: !!(comp.element && document.body.contains(comp.element))
        });
      });
      console.table(rows);
      return rows;
    };

    window.__mv6020ChangeReport = { copied: Object.keys(copied).length, skipped, firstPass, lost, recalculated, repaired, notShown, valid, errors };
    console.info('[MV6020 change report] copied', Object.keys(copied).length, 'keys; skipped', skipped,
                 '; changed by the first apply', firstPass, '; still changed', lost, '; recalculated', recalculated,
                 '; fields repaired', repaired, '; fields not showing the copied value', notShown, '; valid', valid,
                 '; errors', JSON.stringify(errors));
    const problems = new Set([...lost, ...notShown]).size;
    say('success', problems
      ? `Revision ${parent.revision} of ${caseNumber} loaded. ${problems} field(s) were changed by form rules; review them before submitting.`
      : `Revision ${parent.revision} of ${caseNumber} loaded. Make your changes, then submit.`);
  } catch (e) {
    say('error', e instanceof LoadError ? e.message : 'The original report could not be loaded. The form was not changed.');
    // Engine errors name code, not data; still never log submission values.
    if (!(e instanceof LoadError)) console.error('[MV6020 change report] load failed:', e && e.name, e && e.message);
  } finally {
    if (button) button.disabled = false;
  }
})();

