const validatePoliceFileNumber = (input, data) => {
  // Skip validation if input is empty (let required validation handle that)
  if (!input) {
    return true;
  }

  // Check if input contains only numbers and hyphens
  if (!/^[\d-]+$/.test(input)) {
    return "Police File Number must contain only numbers and hyphens";
  }

  const currentYear = new Date().getFullYear();
  const previousYear = currentYear - 1;
  const inputYear = input.slice(0, 4);

  // Check if first 4 characters are numeric
  if (!/^\d{4}/.test(input)) {
    return "Police File Number must start with a 4-digit year";
  }

  const inputYearNum = parseInt(inputYear, 10);
  
  return inputYearNum === currentYear || inputYearNum === previousYear
    ? true
    : `Police File Number must start with either ${currentYear} or ${previousYear}`;
};

valid = validatePoliceFileNumber(input, data);

