const validateCollisionTime = (input, data) => {
  // 1️⃣ If "Time of Collision Unknown" is checked, allow sentinel 27:00 and skip future checks
  if (data?.time_collision_unknown) {
    if (input === "27:00") {
      return true;
    }
    // If the checkbox is on but the value is something else, show a clear message
    return "Time of Collision will be set to 27:00 when 'Time of Collision Unknown' is selected.";
  }

  // 2️⃣ Normal validation path (time must be valid and not in the future if collision date is today)
  if (!input || !data?.date_collision) {
    return true;
  }

  // Browser-local current time
  const now = new Date();

  // Parse HH:mm
  const parts = input.split(":");
  if (parts.length !== 2) {
    return "Enter time in HH:mm format (00:00 - 23:59).";
  }

  const hh = parseInt(parts[0], 10);
  const mm = parseInt(parts[1], 10);

  if (
    isNaN(hh) || isNaN(mm) ||
    hh < 0 || hh > 23 ||
    mm < 0 || mm > 59
  ) {
    return "Enter time in HH:mm format (00:00 - 23:59).";
  }

  // Compare only if collision date is today (local)
  const collisionDate = new Date(data.date_collision);
  collisionDate.setHours(hh, mm, 0, 0);  

  if (collisionDate > now) {
    return "Time of Collision cannot be in the future.";
  }

  return true;
};

// Usage in Form.io custom validation:
valid = validateCollisionTime(input, data);

const validateDateReported = (input, data) => {
  // Ensure both dates exist
  if (!input || !data?.date_collision) {
    return true; // Let required validation handle missing values
  }
  
  const collisionDate = moment(data.date_collision).startOf('day');
  const reportedDate = moment(input).startOf('day');
  
  return reportedDate.isSameOrAfter(collisionDate) ? 
    true : 
    "Date Reported cannot be earlier than Date of Collision";
};
valid = validateDateReported(input, data);

