    instance.root.getComponent('lat_sec').setValue(latDMS.lat_sec)
  }
  
  if((data?.gps_format === 'D' || data?.gps_format === 'C') && data?.long_decim_degrees !== '') {
    const lngDMS = gpsConverter.gpsConverter.convertLongitudeToDMS(data?.long_decim_degrees);
    instance.root.getComponent('long_degree').setValue(lngDMS.long_degree)
    instance.root.getComponent('long_min').setValue(lngDMS.long_min)
    instance.root.getComponent('long_sec').setValue(lngDMS.long_sec)
  }
  
   if(data?.gps_format === 'M' && data?.lat_degree !== '' && data?.lat_min !== '' && data?.lat_sec !== '') {
     const latDecimal = gpsConverter.gpsConverter.convertDMSToLatitude(data?.lat_degree, data?.lat_min, data?.lat_sec);
     instance.root.getComponent('lat_decim_degrees').setValue(latDecimal)
   }
   
   if(data?.gps_format === 'M' && data?.long_degree !== '' && data?.long_min !== '' && data?.long_sec !== '') {
     const lngDecimal = gpsConverter.gpsConverter.convertDMSToLongitude(data?.long_degree, data?.long_min, data?.long_sec);
     instance.root.getComponent('long_decim_degrees').setValue(lngDecimal)
   }
  
}

components.customConditional:
if(instance && !instance.mapSelectedListner){
  
  /**
 * Replaces the JavaScript file in an RSBC service URL with a GeoJSON file
 * @param {string} rsbcUrl - The original RSBC service URL
 * @param {string} geoJsonFileName - The GeoJSON file name to replace with (default: 'ABMS_PROVINCE_SP.geojson')
 * @returns {string} The modified URL with GeoJSON file
 */
function replaceWithGeoJson(rsbcUrl, geoJsonFileName = 'ABMS_PROVINCE_SP.geojson') {
  if (!rsbcUrl || typeof rsbcUrl !== 'string') {
    throw new Error('Invalid URL provided');
  }

  // Find the last occurrence of '/' to locate the file part
  const lastSlashIndex = rsbcUrl.lastIndexOf('/');
  
  if (lastSlashIndex === -1) {
    throw new Error('Invalid URL format: no path separator found');
  }

  // Extract base URL and replace the file portion
  const baseUrl = rsbcUrl.substring(0, lastSlashIndex + 1);
  
  return `${baseUrl}${geoJsonFileName}`;
}

function setGeoJsonUrl() {
  const geoUrl = replaceWithGeoJson(window._env_.REACT_APP_MF_FORMSFLOW_RSBC_SERVICE_URL);
  instance.component.geoJsonUrl = geoUrl
  instance.render()
}

function setLocationInfo(loc_data) {
    instance.root.getComponent("lat_decim_degrees").setValue(loc_data.lat)
    instance.root.getComponent("long_decim_degrees").setValue(loc_data.long)
}

   instance.on('render', (event) => {
     console.log('Form rendered:', event);
    setGeoJsonUrl()
  });
  
  instance.root.on('mapSelected', async (event) => {
    const loc_data = event.data;
    setLocationInfo(loc_data)
  });
  
  instance.root.on('mapCleared', async (event) => {
    instance.root.getComponent("lat_decim_degrees").setValue('')
    instance.root.getComponent("long_decim_degrees").setValue('')
    
    instance.root.getComponent("lat_degree").setValue('')
    instance.root.getComponent("lat_min").setValue('')
    instance.root.getComponent("lat_sec").setValue('')
    instance.root.getComponent("long_degree").setValue('')
    instance.root.getComponent("long_min").setValue('')
    instance.root.getComponent("long_sec").setValue('')
  });

  
};

