   */
  getPositionOptions(entityType) {
    const typeKey = this.extractValue(entityType);

    const optionsMap = {
      'V': this.vehiclePositionOptions,
      'C': this.cyclistPositionOptions,
      'P': this.pedestrianPositionOptions,
      'O': this.otherPositionOptions
    };

    return optionsMap[typeKey] || null;
  }

  /**
   * Get safety equipment options based on entity type and box27 value
   * @param {string|object} entityType - Entity type (V, C, P, O)
   * @param {string|object|null} box27Value - Box 27 value (vehicle type code)
   * @returns {Array|null} - Options array or null
   */
  getSafetyEquipmentOptions(entityType, box27Value = null) {
    const typeKey = this.extractValue(entityType);
    const box27 = this.extractValue(box27Value);

    // Vehicle with motorcycle/moped (50, 51) uses helmet options
    if (typeKey === 'V' && (box27 === '50' || box27 === '51')) {
      return this.motorcycleSafetyEquipmentOptions;
    }

    const optionsMap = {
      'V': this.vehicleSafetyEquipmentOptions,
      'C': this.cyclistSafetyEquipmentOptions,
      'P': this.pedestrianSafetyEquipmentOptions,
      'O': this.otherSafetyEquipmentOptions
    };

    return optionsMap[typeKey] || null;
  }

  /**
   * Get options rules for entity type fields
   * @param {string|object} entityType - Entity type (V, C, P, O)
   * @param {string|object|null} box27Value - Box 27 value for vehicle type
   * @returns {Array|null} - Array of rules with targetField and options
   */
  getEntityTypeOptionsRules(entityType, box27Value = null) {
    const typeKey = this.extractValue(entityType);

    const positionOptions = this.getPositionOptions(entityType);
    const safetyOptions = this.getSafetyEquipmentOptions(entityType, box27Value);

    if (!positionOptions && !safetyOptions) {
      return null;
    }

    const rules = [];

    if (positionOptions) {
      rules.push({
        targetField: 'position_of_person',
        options: positionOptions
      });
    }

    if (safetyOptions) {
      rules.push({
        targetField: 'safety_equipment_used',
        options: safetyOptions
      });
    }

    return rules.length > 0 ? rules : null;
  }

  /**
   * Enable component and clear its value
   */
  enableAndClearComponent(fieldComp) {
    if (!fieldComp) return;
    fieldComp.disabled = false;
    if (fieldComp.component) {
      fieldComp.component.disabled = false;
    }
    fieldComp.setValue('');
  }

  /**
   * Disable a component
   */
  disableComponent(fieldComp) {
    if (!fieldComp) return;
    fieldComp.disabled = true;
    if (fieldComp.component) {
      fieldComp.component.disabled = true;
    }
  }

  /**
   * Reset all fields in editGrid (enable and clear)
   */
  resetAllFields(editGridInstance, fieldKeys = null) {
    const fields = fieldKeys || this.allFields;
    
    if (!editGridInstance || !Array.isArray(editGridInstance.editRows)) {
      return;
    }

    editGridInstance.editRows.forEach(rowInstance => {
      fields.forEach(fieldKey => {
        const fieldComp = this.findComponentRecursive(rowInstance.components, fieldKey);
        if (fieldComp) {
          this.enableAndClearComponent(fieldComp);
        }
      });
    });
  }

  /**
 * Apply options rules to editGrid components
 * @param {object} editGridInstance - Form.io editGrid instance
 * @param {string|object} entityType - Entity type
 * @param {string|object|null} box27Value - Box 27 value
 */
applyEntityTypeOptionsRules(editGridInstance, entityType, box27Value = null) {
  if (!editGridInstance || !Array.isArray(editGridInstance.editRows)) {
    return;
  }

  console.log('Applying entity type options rules for entity type:', entityType, 'box27:', box27Value);

  const rules = this.getEntityTypeOptionsRules(entityType, box27Value);
  
  if (!rules || rules.length === 0) {
    return;
  }

  editGridInstance.editRows.forEach(rowInstance => {
    rules.forEach(rule => {
      const fieldComp = this.findComponentRecursive(rowInstance.components, rule.targetField);
      if (fieldComp) {
        fieldComp.setValue('');
        fieldComp.component.data.values = rule.options;
        fieldComp.redraw();
      }
    });
  });
}

  /**
   * Apply all entity type rules (reset, options, auto-set/disable)
   * @param {object} editGridInstance - Form.io editGrid instance
   * @param {string|object} entityType - Entity type
   * @param {string|object|null} box27Value - Box 27 value
   */
  applyEntityTypeRules(editGridInstance, entityType, box27Value = null) {
    if (!editGridInstance || !Array.isArray(editGridInstance.editRows)) {
      return;
    }

    // Step 1: Reset all fields (enable and clear)
    this.resetAllFields(editGridInstance);

    // Step 2: Set options based on entity type and box27
    this.applyEntityTypeOptionsRules(editGridInstance, entityType, box27Value);

    // Step 3: Get rule for the current entity type (auto-set and disable)
    const rule = this.getEntityTypeRule(entityType);
    
    if (!rule) {
      return;
    }

    // Step 4: Apply rule - set value and disable targeted fields
    editGridInstance.editRows.forEach(rowInstance => {
      rule.targetFields.forEach(fieldKey => {
        const fieldComp = this.findComponentRecursive(rowInstance.components, fieldKey);
        if (fieldComp) {
          fieldComp.setValue(rule.value);
          this.disableComponent(fieldComp);
        }
      });
    });
  }

  /**
   * Alias for backward compatibility
   */
  applyRulesToGrid(editGridInstance, entityType, box27Value = null) {
    this.applyEntityTypeRules(editGridInstance, entityType, box27Value);
  }

  /**
   * Get all entity type rules
   */
  getAllRules() {
    return { ...this.entityTypeRules };
  }
}

// Initialize on instance if available
if (typeof instance !== 'undefined' && typeof instance.entityTypeInvolvedPersonFieldManager === 'undefined') {
