/**
 * Vehicle Parked Handler
 * Resets direction of travel when vehicle is not parked
 */

const COMPONENT_KEYS = {
  DIR_OF_TRAVEL: 'dir_of_travel'
};

/**
 * Recursively finds a component instance by key within a component tree
 */
function findComponentByKey(components, key) {
  for (const comp of components) {
    if (comp.component?.key === key) return comp;
    if (Array.isArray(comp.components)) {
      const found = findComponentByKey(comp.components, key);
      if (found) return found;
    }
  }
  return null;
}

/**
 * Traverses up the component tree to find the parent EditGrid
 */
function findParentEditGrid(instance) {
  let parent = instance.parent;
  while (parent && parent.component?.type !== 'editgrid') {
    parent = parent.parent;
  }
  return parent;
}

/**
 * Resolves a component instance - row-scoped if inside EditGrid, otherwise global
 */
function getComponentInstance(key, currentInstance, rowIndex) {
  if (typeof rowIndex === 'number') {
    const parentGrid = findParentEditGrid(currentInstance);
    const rowComponents = parentGrid?.editRows?.[rowIndex]?.components;
    if (rowComponents) {
      return findComponentByKey(rowComponents, key);
    }
  }
  return currentInstance.root?.getComponent(key) ?? null;
}

/**
 * Clears component value and enables it
 */
function resetComponent(component) {
  if (!component) return;
  
  component.setValue('');
  component.disabled = false;
  if (component.component) {
    component.component.disabled = false;
  }
  component.redraw();
}

/**
 * Resets direction of travel when vehicle_parked is unchecked
 * @param {boolean} isParked - vehicle_parked checkbox state
 * @param {Object} currentInstance - Current component instance
 * @param {number|undefined} rowIndex - Row index if inside EditGrid
 */
function handleVehicleParkedChange(isParked, currentInstance, rowIndex) {
  if (!isParked) {
    const dirOfTravel = getComponentInstance(COMPONENT_KEYS.DIR_OF_TRAVEL, currentInstance, rowIndex);
    resetComponent(dirOfTravel);
  }
}

// Register change handler (only once)
if (instance && !instance.hasEventHandler?.('change')) {
  instance.on('change', (event) => {
    const changed = event.changed;
    if (changed?.component?.key === 'vehicle_parked') {
      handleVehicleParkedChange(
        changed.value,
        changed.instance,
        changed.instance?.rowIndex
      );
    }
  });
}

