(async function() {
  const dlNumber = row?.driver_license_num;
  if (!dlNumber) {
    window.toast.error("Enter drivers license number");
    return;
  }
  
  const authToken = localStorage.getItem('AUTH_TOKEN');
  if (!authToken) {
    window.toast.error('Authentication token not found');
    return;
  }
  
  try {
    const apiUrl = `${window._env_.REACT_APP_RSBC_API_URL}/api/v1/icbc/drivers/${dlNumber}`;
    
    const response = await fetch(apiUrl, {
      headers: {
        'Authorization': `Bearer ${authToken}`,
        'Content-Type': 'application/json'
      }
    });
    
    if (!response.ok) {
      throw new Error('API request failed');
    }
    
    const resp = await response.json();
    
    if (!_.isEmpty(resp)) {
      const party = resp.party;
      const address = party.addresses[0];
      
      // Update row object
      row.surname = party.lastName;
      row.given_name = party.firstName;
      
      if (party.birthDate) {
        row.date_of_birth = moment(party.birthDate).tz("America/Vancouver").toDate();
      }
      
      row.driver_address = address.addressLine1;
      row.driver_city = address.city;
      row.driver_postal = address.postalCode;
      row.driver_prov_state = {
        "value": "CA_BC",
        "label": "BRITISH COLUMBIA"
      };
      
      // Find the editGrid component and trigger redraw
      let component = instance;
      while (component && component.component.type !== 'editgrid') {
        component = component.parent;
      }
      
      if (component) {
        component.redraw();
        // OR use triggerChange to also fire validation/calculations
        component.triggerChange();
      }
      
      window.toast.success('Driver details loaded successfully');
    } else {
      window.toast.error("No driver was found for DL " + dlNumber);
    }
  } catch (error) {
    window.toast.error('Failed to fetch driver details. Please try again.');
    console.error(error);
  }
})();

