/**
 * Vehicle Owner Auto-Population Handler
 * Copies driver name/address to vehicle owner fields when checkbox is checked
 */

// Constants for component keys
const COMPONENT_KEYS = {
  VEHICLE_OWNER_NAME: 'vehicle_owner_name',
  VEHICLE_OWNER_ADDRESS: 'vehicle_owner_address'
};

/**
 * Recursively finds a component instance by key within a component tree
 * @param {Array} components - Array of Form.io component instances
 * @param {string} key - Component key to find
 * @returns {Object|null} Component instance or null
 */
function findComponentByKey(components, key) {
  for (const comp of components) {
    if (comp.component?.key === key) return comp;
    if (Array.isArray(comp.components)) {
      const found = findComponentByKey(comp.components, key);
      if (found) return found;
    }
  }
  return null;
}

/**
 * Traverses up the component tree to find the parent EditGrid
 * @param {Object} instance - Current component instance
 * @returns {Object|null} Parent EditGrid instance or null
 */
function findParentEditGrid(instance) {
  let parent = instance.parent;
  while (parent && parent.component?.type !== 'editgrid') {
    parent = parent.parent;
  }
  return parent;
}

/**
 * Resolves a component instance - row-scoped if inside EditGrid, otherwise global
 * @param {string} key - Component key
 * @param {Object} currentInstance - Current component instance for context
 * @param {number|undefined} rowIndex - Row index if inside EditGrid
 * @returns {Object|null} Component instance or null
 */
function getComponentInstance(key, currentInstance, rowIndex) {
  if (typeof rowIndex === 'number') {
    const parentGrid = findParentEditGrid(currentInstance);
    const rowComponents = parentGrid?.editRows?.[rowIndex]?.components;
    if (rowComponents) {
      return findComponentByKey(rowComponents, key);
    }
  }
  return currentInstance.root?.getComponent(key) ?? null;
}

/**
 * Batch retrieves multiple components by key
 * @param {string[]} keys - Array of component keys
 * @param {Object} currentInstance - Current component instance
 * @param {number|undefined} rowIndex - Row index if inside EditGrid
 * @returns {Object} Map of key -> component instance (null if not found)
 */
function getComponents(keys, currentInstance, rowIndex) {
  return keys.reduce((acc, key) => {
    acc[key] = getComponentInstance(key, currentInstance, rowIndex);
    return acc;
  }, {});
}


/**
 * Clears component value and enables it
 * @param {Object} component - Form.io component instance
 */
function resetComponent(component) {
  if (!component) return;
  
  component.setValue('');
  component.disabled = false;
  if (component.component) {
    component.component.disabled = false;
  }
  component.redraw();
}

/**
 * Handles vehicle owner name/address reset  based on checkbox state
 * @param {boolean} checked - Checkbox state
 * @param {Object} currentInstance - Current component instance
 * @param {number|undefined} rowIndex - Row index if inside EditGrid
 */
function handleVehicleOwnerNameAndAddress(checked, currentInstance, rowIndex) {
  const components = getComponents(Object.values(COMPONENT_KEYS), currentInstance, rowIndex);
  
  const { vehicle_owner_name, vehicle_owner_address } = components;
  
  if (!checked) {
    resetComponent(vehicle_owner_name);
    resetComponent(vehicle_owner_address);
  }
}

// Register change handler (only once)
if (instance && !instance.hasEventHandler?.('change')) {
  instance.on('change', (event) => {
    const changed = event.changed;
    if (changed?.component?.key === instance.component.key) {
      handleVehicleOwnerNameAndAddress(
        changed.value,
        changed.instance,
        changed.instance?.rowIndex
      );
    }
  });
}

