if (!editGrid || !Array.isArray(editGrid.editRows)) {
  valid = true;
  return valid
}

// Helper function to find component recursively
function findComponentRecursive(components, key) {
  for (const comp of components) {
    if (comp.component && comp.component.key === key) {
      return comp;
    }
    if (Array.isArray(comp.components)) {
      const nested = findComponentRecursive(comp.components, key);
      if (nested) return nested;
    }
  }
  return null;
}

// Calculate total estimated vehicle damage
const currentRowIndex = self.rowIndex;

totalDamage = 0;
editGrid.editRows.forEach((rowInstance, index) => {
  const damageComp = findComponentRecursive(rowInstance.components, 'estimated_vehicle_damage');
  if (damageComp) {
    // Use current input value for the row being edited
    if (index === currentRowIndex) {
      damageValue = input;
    } else {
      damageValue = damageComp.getValue();
    }

    // Convert to number, handle null/undefined/empty values
    const numericValue = parseFloat(damageValue) || 0;
    totalDamage += numericValue;
  }
});

// Check if total exceeds limit for collision scenario "07"
const DAMAGE_LIMIT = 10000;
if (totalDamage > DAMAGE_LIMIT) {
  valid = `Total estimated vehicle damage ($${totalDamage.toLocaleString()}) exceeds the $${DAMAGE_LIMIT.toLocaleString()} limit for collision scenario "07" (Property damage only, estimated value under $10k).`;
} else {
  valid = true;
}

