validate.custom:
const isEditing = instance.editRows && instance.editRows.some(function(row) {
  return row.state !== "saved";
});
if (isEditing) {
  valid = "Please save all involved person before proceeding"
}
// Check if vehicle is NOT parked (validations only apply if not parked)
else if (!row?.vehicle_parked && !row?.unknown_entity) {

  // 1. Requirement: Must have at least one Involved Person
  if (instance.editRows.length === 0) {
    valid = "Involved Person 01 is required for this entity type. Please complete the Involved Person information to continue.";
  }
  // 2. Validate content of rows
  else {
    // --- A. Check First Person Matches Entity ---
    const firstPerson = instance.editRows[0].data;
    const mismatchFields = [];

    // Normalize helper
    const normalize = (val) => (val || '').toString().trim().toUpperCase();

    const entitySurname = normalize(row.surname);
    const personSurname = normalize(firstPerson.surname);
    if (entitySurname !== personSurname) mismatchFields.push("Surname");

    const entityGivenName = normalize(row.given_name);
    const personGivenName = normalize(firstPerson.given_name);
    if (entityGivenName !== personGivenName) mismatchFields.push("Given Name");

    // Loose equality for age to handle string vs number
    if (row.age_at_collision != firstPerson.age) mismatchFields.push("Age");

    const entitySex = (row.sex?.value || row.sex || '').toString();
    const personSex = (firstPerson.sex?.value || firstPerson.sex || '').toString();
    if (entitySex !== personSex) mismatchFields.push("Sex");

    if (mismatchFields.length > 0) {
      valid = `The first Involved Person must match the Entity details. The following fields do not match: ${mismatchFields.join(', ')}.`;
    }
    
    // --- B. Check for Duplicate Entries (NEW VALIDATION) ---
    // Only run this if the previous validation passed
    if (valid === true) {
      const seenSignatures = new Set();
      let hasDuplicates = false;

      // Iterate through all rows to check for duplicates
      for (let i = 0; i < instance.editRows.length; i++) {
        const person = instance.editRows[i].data;
        
        const s = normalize(person.surname);
        const g = normalize(person.given_name);
        const a = (person.age || '').toString();
        const x = (person.sex?.value || person.sex || '').toString();

        // Create a unique signature string
        const signature = `${s}|${g}|${a}|${x}`;

        // If we have seen this combination before, flag it
        if (seenSignatures.has(signature)) {
          hasDuplicates = true;
          break; // Stop checking after finding the first duplicate
        }
        seenSignatures.add(signature);
      }

      if (hasDuplicates) {
        valid = "Duplicate entries detected. Two or more Involved Persons have the same Surname, Given Name, Age, and Sex.";
      }
    }
  }
}

