// Helper function to find component recursively within a component tree
function findComponentRecursive(components, key) {
  for (const comp of components) {
    if (comp.component && comp.component.key === key) {
      return comp;
    }
    if (Array.isArray(comp.components)) {
      const nested = findComponentRecursive(comp.components, key);
      if (nested) return nested;
    }
  }
  return null;
}

function handleEventTypeChange(instance, selectedValue, rowIndex) {
  const components = getRelevantComponents(instance, rowIndex);

  // Reset all fields first
  resetAllFields(components);

  // Apply specific configurations based on event type
  if (selectedValue.value === "notInjured") {
    configureNotInjured(components);
  } else if (selectedValue.value === "deceased") {
    configureDeceased(components);
  } else if (selectedValue.value === "injured") {
    configureInjured(components);
  } else if (selectedValue.value === "noDriver") {
    configureNoDriver(components);
  }
  // else: fields remain reset (enabled and empty)
}

function getRelevantComponents(instance, rowIndex) {
  // Find the parent edit grid
  let editGridComponent = instance.parent;
  while (editGridComponent && editGridComponent.component.type !== 'editgrid') {
    editGridComponent = editGridComponent.parent;
  }

  if (!editGridComponent || !editGridComponent.editRows) {
    return {};
  }

  // Use the provided rowIndex to get the correct row
  if (rowIndex === undefined || !editGridComponent.editRows[rowIndex]) {
    return {};
  }

  const currentRowComponents = editGridComponent.editRows[rowIndex].components;

  return {
    severe_injury_location: findComponentRecursive(currentRowComponents, "severe_injury_location"),
    injury_type: findComponentRecursive(currentRowComponents, "injury_type"),
    injury_classification: findComponentRecursive(currentRowComponents, "injury_classification"),
    consciousness_state: findComponentRecursive(currentRowComponents, "consciousness_state"),
    position_of_person: findComponentRecursive(currentRowComponents, "position_of_person")
  };
}

function resetAllFields(components) {
  Object.values(components).forEach(componentCurrent => {
    if (componentCurrent) {
      componentCurrent.setValue('');
      componentCurrent.disabled = false;
      if (componentCurrent.originalComponent) {
        componentCurrent.originalComponent.disabled = false;
      }

      //
      if(componentCurrent.key === 'consciousness_state'){
        // Removed as its not working and setting  to originalComponent
        //componentCurrent.component.data.json = row?.state_of_con_intial_values

        componentCurrent.originalComponent.data.json = initial_conscious_options;
        componentCurrent.redraw()
      }
    }
  });
}

function configureNotInjured(components) {
  setValueAndDisable(components.severe_injury_location, {
    "label": "01 NO INJURY",
    "value": "01"
  });
  setValueAndDisable(components.injury_type, {
    "label": "01 NONE",
    "value": "01"
  });
  setValueAndDisable(components.consciousness_state, {
    "label": "01 APPARENTLY NORMAL",
    "value": "01"
  });
  setValueAndDisable(components.injury_classification, {
    "label": "01 NO APPARENT INJURIES",
    "value": "01"
  });
}

function configureInjured(components) {
  setValuesBox20A(components.injury_classification);
  setValuesBox18ForInjured(components.consciousness_state)
}

function configureDeceased(components) {
  setValuesBox18(components.consciousness_state);
  setValueAndDisable(components.injury_classification, {
    "label": "98 APPARENTLY DECEASED OR DECEASED",
    "value": "98"
  });
}

function configureNoDriver(components) {
  Object.values(components).forEach(componentCurrent => {
    if (componentCurrent) {
      componentCurrent.setValue('');
      componentCurrent.disabled = true;
      if (componentCurrent.originalComponent) {
        componentCurrent.originalComponent.disabled = true;
      }
    }
  });
}

function setValueAndDisable(currentComp, value) {
  if (currentComp) {
    currentComp.setValue(value);
    currentComp.disabled = true;
    if (currentComp.originalComponent) {
      currentComp.originalComponent.disabled = true;
    }
    currentComp.redraw();
  }
}

