trigger.javascript:
const keys_to_look = [
  'damage_location_code',
  'second_contact',
  'pre_collision_vehicle_action_first_event',
  'vehicle_type',
  'vehicle_use',
  'contributing_factor_1',
  'contributing_factor_2',
  'contributing_factor_3',
  'contributing_factor_4'
];

const person_keys_to_look = ['position_of_person'];

const data_level_keys = [
  'road_class',
  'traffic_flow',
  'collision_loc',
  'land_usage',
  'road_type',
  'traffic_control',
  'roadway_character',
  'roadway_surface_cond',
  'weather_cond',
  'lighting_cond',
  'primary_collision_occ_code',
  'first_contact_event',
  'pedestrian_action'
]; // Add other data-level keys here

const hasTargetValue = (obj, keys) => keys.some(key => obj[key]?.value === "99");

let police_comments_required = hasTargetValue(data, data_level_keys);

// Check entities array
if (!police_comments_required && Array.isArray(data.entities)) {
  police_comments_required = data.entities.some(entity => {
  
    // if entity num is 99
    if(entity?.entity_num === "99") return true;
    
    // Check entity-level keys
    if (hasTargetValue(entity, keys_to_look)) return true;
    
    // Check involved_persons within each entity
    if (Array.isArray(entity.involved_persons)) {
      return entity.involved_persons.some(person => 
        hasTargetValue(person, person_keys_to_look)
      );
    }
    
    return false;
  });
}

result = police_comments_required;

const keys_to_look = [
  'damage_location_code',
  'second_contact',
  'pre_collision_vehicle_action_first_event',
  'vehicle_type',
  'vehicle_use',
  'contributing_factor_1',
  'contributing_factor_2',
  'contributing_factor_3',
  'contributing_factor_4'
];
const person_keys_to_look = ['position_of_person'];
const data_level_keys = [
  'road_class',
  'traffic_flow',
  'collision_loc',
  'land_usage',
  'road_type',
  'traffic_control',
  'roadway_character',
  'roadway_surface_cond',
  'weather_cond',
  'lighting_cond',
  'primary_collision_occ_code',
  'first_contact_event',
  'pedestrian_action'
];

// Flatten all components for lookup (keys will be like 'entities.damage_location_code')
const componentMap = utils.flattenComponents(form.components);

// Helper to get component label by key with optional prefix for nested components
const getComponentLabel = (key, prefix = '') => {
  const lookupKey = prefix ? `${prefix}.${key}` : key;
  return componentMap[lookupKey]?.label || key;
};

const fieldsWithValue99 = [];

// Helper to collect fields with value 99
const collectFields = (obj, keys, displayPrefix = '', keyPrefix = '') => {
  keys.forEach(key => {
    if (obj[key]?.value === "99") {
      const label = getComponentLabel(key, keyPrefix);
      fieldsWithValue99.push(displayPrefix ? `${displayPrefix}: ${label}` : label);
    }
  });
};

// Check data-level keys (no key prefix)
collectFields(data, data_level_keys);

// Check entities array
if (Array.isArray(data.entities)) {
  data.entities.forEach((entity, idx) => {
    const entityPrefix = `Entity ${idx + 1}`;
    
    // Check if entity_num is 99
    if (entity?.entity_num === "99") {
      const label = getComponentLabel('entity_num', 'entities');
      fieldsWithValue99.push(`${entityPrefix}: ${label}`);
    }
    
    // Check entity-level keys (key prefix: 'entities')
    collectFields(entity, keys_to_look, entityPrefix, 'entities');
    
    // Check involved_persons within each entity
    if (Array.isArray(entity.involved_persons)) {
      entity.involved_persons.forEach((person, pIdx) => {
        const personPrefix = `${entityPrefix} - Person ${pIdx + 1}`;
        // Key prefix: 'entities.involved_persons'
        collectFields(person, person_keys_to_look, personPrefix, 'entities.involved_persons');
      });
    }
  });
}

// Store the list for use in actions
instance.fieldsWithValue99 = fieldsWithValue99;

// Return boolean for trigger
result = fieldsWithValue99.length > 0;

actions.customAction:
const fieldsList = instance.fieldsWithValue99 || [];

const listHtml = fieldsList.length > 0 
  ? '<ul style="list-style: disc; padding-left: 20px; margin: 10px 0 0 0;">' + 
    fieldsList.map(field => `<li style="margin: 5px 0;">${field}</li>`).join('') + 
    '</ul>'
  : '<p style="margin: 10px 0 0 0;"><em>No fields with value "99" found.</em></p>';

component.html = `<div style="background-color: #fff3cd; border-left: 4px solid #ffc107; padding: 15px; margin: 10px 0; border-radius: 4px;">
  <p style="margin: 0; color: #856404; font-size: 14px;">
    The following fields have been answered with "99" - ensure that you have addressed them in <strong>Box 99 Police Comments above:</strong>
  </p>
  ${listHtml}
</div>`;

