// } else {
//   value = "N"
// }

if (data.total_killed == 0) {
  value = "NA"
} else if (data.countable_fatal_total > 0) {
  value = "Y"
} else {
  value = "N"
}

 const counts = {
    notInjured: 0,
    injured: 0,
    deceased: 0
  };

  // Aggregate counts across all entities
  data.entities?.forEach(entity => {
    entity.involved_persons?.forEach(person => {
      const status = person.status?.value ?? person.status;
      if (status in counts) {
        counts[status]++;
      }
    });
  });

  // Apply business rules
  if (counts.deceased > 0) {
    value = 5;
  } else if (counts.injured > 0 && !counts.deceased) {
    value = 3;
  } else if (data.total_est_damage >= 10000) {
    value = 2;
  } else {
    value = 0;
  }

const totalEstimatedDamage = data.entities.reduce((total, entity) => {
  const damage = parseFloat(entity.estimated_vehicle_damage) || 0;
  return total + damage;
}, 0);

value = totalEstimatedDamage + (data.prop_damage_est_value ? data.prop_damage_est_value : 0)

