 );

const totalDeceased = getTotalDeceasedPersons(data.entities);

value = totalDeceased

const getTotalVehicles = (entities) => 
 entities.filter(entity => entity.entity_type.value === "V").length;

const totalVehicles = getTotalVehicles(data.entities);

value = totalVehicles

// No of involved person with Box 18 (State of Consciousness) = 06 – Apparently Dead
const getDeceasedCount = (entities) => 
 entities.reduce((count, entity) => 
   count + (entity.involved_persons?.filter(person => person.consciousness_state.value === "06").length || 0), 0
 );

value = getDeceasedCount(data.entities);

